insert into public.products(id,name,sku,category,description,price,image_url,stock) values
('a1000000-0000-4000-8000-000000000001','Everyday Canvas Tote','ZM-BAG-001','แฟชั่น','กระเป๋าผ้าแคนวาสเนื้อหนา สีธรรมชาติ เรียบง่ายแต่ใส่ใจทุกรายละเอียด พกความสบายไปกับคุณได้ทุกวัน',390,'/images/bag.svg',24),
('a1000000-0000-4000-8000-000000000002','Slow Living Bottle','ZM-LIF-001','ไลฟ์สไตล์','ขวดน้ำสเตนเลสเก็บอุณหภูมิ 500 มล. สีเขียวเซจ คู่ใจในทุกกิจกรรมของวัน',590,'/images/bottle.svg',30),
('a1000000-0000-4000-8000-000000000003','Cloud Wireless Headphones','ZM-TEC-001','แก็ดเจ็ต','หูฟังไร้สายดีไซน์มินิมอล น้ำหนักเบา ครอบหูนุ่มสบาย ให้เสียงเพลงอยู่กับคุณตลอดวัน',1290,'/images/headphones.svg',12),
('a1000000-0000-4000-8000-000000000004','Mushroom Table Lamp','ZM-HOM-001','ของแต่งบ้าน','โคมไฟทรงเห็ดแสงวอร์มไวต์ เติมความอบอุ่นให้มุมโปรดของคุณ',890,'/images/lamp.svg',18),
('a1000000-0000-4000-8000-000000000005','Sunday Ceramic Mug','ZM-LIF-002','ไลฟ์สไตล์','แก้วเซรามิกสีเอิร์ธโทน 350 มล. ให้กาแฟยามเช้ากลายเป็นช่วงเวลาพิเศษ',290,'/images/cup.svg',40),
('a1000000-0000-4000-8000-000000000006','Essential Cotton Tee','ZM-FAS-002','แฟชั่น','เสื้อยืดผ้าคอตตอนทรงสบาย สีเซจ ไซซ์ฟรี ใส่ง่าย แมตช์ได้ทุกวัน',450,'/images/shirt.svg',25),
('a1000000-0000-4000-8000-000000000007','Calm Ceramic Vase','ZM-HOM-002','ของแต่งบ้าน','แจกันเซรามิกทรงออร์แกนิก สีครีมธรรมชาติ เติมชีวิตให้ห้องด้วยรายละเอียดเล็กๆ',490,'/images/vase.svg',16),
('a1000000-0000-4000-8000-000000000008','Little Room Speaker','ZM-TEC-002','แก็ดเจ็ต','ลำโพงบลูทูธแบบพกพา ดีไซน์เรโทรขนาดกะทัดรัด เติมเสียงเพลงให้ทุกพื้นที่',790,'/images/speaker.svg',20) on conflict(id) do nothing;
